          <div className="cart-total">
            <strong>Total: ${total.toFixed(2)}</strong>
          </div>
          <button 
            className="checkout-btn"
            onClick={() => setCheckoutStatus('processing')}
          >
            {checkoutStatus === 'processing' ? 'Processing...' : 'Checkout'}
